<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\Testimonial;use Illuminate\Http\Request;use Illuminate\View\View;use Illuminate\Http\RedirectResponse;
class TestimonialAdminController extends Controller {public function index():View{return view('admin.testimonials.index',['items'=>Testimonial::latest()->paginate(25)]);}public function store(Request $r):RedirectResponse{$v=$r->validate(['customer_name'=>'required|string|max:120','title'=>'nullable|string|max:160','city'=>'nullable|string|max:100','rating'=>'required|integer|min:1|max:5','content'=>'required|string|max:2000','is_published'=>'nullable|boolean']);$v['is_published']=(bool)($v['is_published']??false);Testimonial::create($v);return back()->with('success','Témoignage enregistré.');}public function update(Request $r,Testimonial $item):RedirectResponse{$v=$r->validate(['customer_name'=>'required|string|max:120','title'=>'nullable|string|max:160','city'=>'nullable|string|max:100','rating'=>'required|integer|min:1|max:5','content'=>'required|string|max:2000','is_published'=>'nullable|boolean']);$v['is_published']=(bool)($v['is_published']??false);$item->update($v);return back()->with('success','Témoignage modifié.');}public function toggle(Testimonial $item):RedirectResponse{$item->update(['is_published'=>!$item->is_published]);return back()->with('success','Publication mise à jour.');}public function destroy(Testimonial $item):RedirectResponse{$item->delete();return back()->with('success','Témoignage supprimé.');}}
